bounded_host_request.command:
set -euo pipefail
source_sha=82c02b1e85fa7749ddaa3f50d879ea88795778a3
target="$HOME/.local/share/gace-create-videobot/sticker-poll-$source_sha"
name=gace-createvdobot-videobot-poll-1
test -f "$target/src/runtime/creatorPollingMain.mjs" || { echo STK04_SOURCE_MISSING;exit 61; }
test "$(docker image inspect -f '{{.Config.User}}' create-videobot:local-poll)" = node || { echo STK04_IMAGE_USER_MISMATCH;exit 62; }
test "$(docker inspect -f '{{.State.Running}}' "$name" 2>/dev/null)" = true || { echo STK04_CURRENT_CONTAINER_MISSING;exit 63; }
pg="$(docker ps --format '{{.Names}}' | grep -Ei '(^|[-_])postgres([-_]|$)' || true)"
test "$(printf '%s\n' "$pg" | sed '/^$/d' | wc -l)" -eq 1 || { echo STK04_POSTGRES_NOT_UNIQUE;exit 64; }
db_source="$(docker inspect -f '{{range .Mounts}}{{if eq .Destination "/run/secrets/db_password"}}{{.Source}}{{end}}{{end}}' "$pg")"
token="$(docker inspect -f '{{range .Mounts}}{{if eq .Destination "/run/secrets/videobot_telegram_token"}}{{.Source}}{{end}}{{end}}' "$name")"
test -f "$db_source" && test ! -L "$db_source" && test -f "$token" && test ! -L "$token" || { echo STK04_EXISTING_SECRETS_INVALID;exit 65; }
user="$(docker exec "$pg" sh -c 'printf %s "$POSTGRES_USER"')"
net="$(docker inspect -f '{{range $k,$v := .NetworkSettings.Networks}}{{println $k}}{{end}}' "$pg" | sed '/^$/d')"
test -n "$user" && test "$net" = deploy_default || { echo STK04_POSTGRES_OWNER_INVALID;exit 66; }
other="$(docker ps --format '{{.Names}}' | grep -Ei 'create-videobot|createvdobot|videobot-poll|videobot-telegram' | grep -Fxv "$name" || true)"
test -z "$other" || { echo STK04_DUPLICATE_BOT_CONSUMER;exit 67; }
secret_dir="$HOME/.local/state/create-videobot/secrets"
umask 077
mkdir -p "$secret_dir"
chmod 700 "$secret_dir"
db_target="$secret_dir/gserver_postgres_password"
if test -e "$db_target";then
 test -f "$db_target" && test ! -L "$db_target" || { echo STK04_PRIVATE_DB_SECRET_DEST_INVALID;exit 68; }
 if ! cmp -s "$db_source" "$db_target";then
  install -m 600 "$db_source" "$db_target" || { echo STK04_SECRET_REFRESH_FAILED;exit 69; }
 fi
else
 install -m 600 "$db_source" "$db_target" || { echo STK04_SECRET_PREPARE_FAILED;exit 70; }
fi
chmod 600 "$db_target"
node_uid="$(docker run --rm --network none --pull never --entrypoint id create-videobot:local-poll -u)"
test "$(stat -c '%u' "$db_target")" = "$node_uid" && test "$(stat -c '%a' "$db_target")" = 600 && cmp -s "$db_source" "$db_target" || { echo STK04_PRIVATE_DB_SECRET_VERIFICATION_FAILED;exit 71; }
echo STK04_PRIVATE_SECRET_OWNER_AND_CONTENT=PASS
export VIDEOBOT_TELEGRAM_TOKEN_SOURCE="$token"
export VIDEOBOT_DB_PASSWORD_SOURCE="$db_target"
export GSERVER_POSTGRES_USER="$user"
export GSERVER_POSTGRES_NETWORK="$net"
docker compose -p gace-createvdobot -f "$target/deploy/compose.videobot.poll.yaml" config --quiet || { echo STK04_COMPOSE_CONFIG_INVALID;exit 72; }
docker compose -p gace-createvdobot -f "$target/deploy/compose.videobot.poll.yaml" up -d --no-build --force-recreate videobot-poll >/dev/null 2>&1 || { echo STK04_RECREATE_FAILED;exit 73; }
sleep 10
test "$(docker inspect -f '{{.State.Running}}' "$name" 2>/dev/null)" = true || { echo STK04_BOT_NOT_RUNNING;exit 74; }
docker logs --tail 100 "$name" 2>&1 | grep -q '^CREATOR_DM_POLL_READY=PASS$' || { echo STK04_BOT_NOT_READY;exit 75; }
echo STK04_PRIVATE_DM_READY=PASS
echo STK04_NO_OTHER_BOT_RESTARTED=YES
docker logs --tail 100 "$name" 2>&1 | grep -E '^CREATOR_(DM|GATE|POLL)_' | tail -n 8 || true
